import numpy as np

def build(agent, rewards=(), movers=(), prev=None):
    x = np.zeros(500)
    def s(r,c,ch):
        x[(r*10+c)*5+ch] = 1.0
    for r in range(10):
        for c in range(10):
            if r in (0,9) or c in (0,9):
                s(r,c,3)                      # border walls
    s(agent[0],agent[1],0)                    # agent
    for (r,c) in rewards: s(r,c,2)            # reward targets
    for (r,c) in movers:  s(r,c,1)            # movers
    p = agent if prev is None else prev
    s(p[0],p[1],4)                            # previous frame
    return x

