import numpy as np

def obs(agent, mover=None, reward=None):
    x = np.zeros(500)
    for r in range(10):
        for c in range(10):
            if r == 0 or r == 9 or c == 0 or c == 9:
                x[(r*10+c)*5 + 3] = 1.0          # border walls -> ch3
    def setcell(r, c, ch):
        x[(r*10+c)*5 + ch] = 1.0
    setcell(agent[0], agent[1], 0)               # agent -> ch0
    if mover is not None:  setcell(mover[0], mover[1], 1)
    if reward is not None: setcell(reward[0], reward[1], 2)
    return x

