    'empty':        obs((4,4)),
    'reward_left':  obs((4,4), reward=(4,3)),
    'reward_right': obs((4,4), reward=(4,5)),
    'reward_up':    obs((4,4), reward=(3,4)),
    'reward_down':  obs((4,4), reward=(5,4)),
    'mover_left':   obs((4,4), mover=(4,3)),
    'mover_right':  obs((4,4), mover=(4,5)),
    'mover_up':     obs((4,4), mover=(3,4)),
    'mover_down':   obs((4,4), mover=(5,4)),
}
